#include <iostream>
#include <fstream>
#include <string>
#include <map>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("dziennik.txt");
    string imie;
    int ocena;
    map<int, int> hist;
    int suma = 0, cnt = 0;
    while (plik >> imie >> ocena) {
        hist[ocena]++;
        suma += ocena;
        cnt++;
    }
    cout << "Histogram ocen:" << endl;
    int maxOcena = 0, maxCnt = 0;
    for (auto& p : hist) {
        cout << "   Ocena " << p.first << ": " << p.second << endl;
        if (p.second > maxCnt) {
            maxCnt = p.second;
            maxOcena = p.first;
        }
    }
    cout << "Najczestsza ocena: " << maxOcena << " (" << maxCnt << " razy)" << endl;
    cout << fixed << setprecision(2);
    cout << "Srednia ocen: " << (double)suma / cnt << endl;
    return 0;
}
```

Weryfikacja:
- Ocena 2: Piotr, Darek = 2
- Ocena 3: Jan, Marek, Zosia, Filip = 4
- Ocena 4: Ewa, Tomek, Adam, Bartek, Magda = 5
- Ocena 5: Anna, Kasia, Ola, Iwona = 4
- Najczestsza: 4 (5 razy)
- Suma: 5+3+4+2+5+4+3+5+4+3+4+5+2+4+3 = 56
- Srednia: 56/15 = 3.7333... ≈ 3.73
